<?php $plural=$domain==='career'?'careers':'bursaries';?><div class="d-flex justify-content-between"><h1><?=$staff?'Application review':'My '.ucfirst($plural).' applications'?></h1><?php if(!$staff):?><a href="<?=e(url('/'.$plural))?>">Browse opportunities</a><?php endif;?></div><?php if(!$applications):?><div class="alert alert-info">No applications found.</div><?php endif;?><div class="table-responsive"><table class="table"><thead><tr><th>Reference</th><th>Opportunity</th><?php if($staff):?><th>Applicant</th><?php endif;?><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($applications as $a):?><tr><td><a href="<?=e(url(($staff?'/admin':'').'/'.$plural.'/applications/'.$a['application_reference']))?>"><?=e($a['application_reference'])?></a></td><td><?=e($a['title'])?></td><?php if($staff):?><td><?=e($a['applicant_name'])?></td><?php endif;?><td><?=e(str_replace('_',' ',$a['status']))?></td><td><?=e($a['updated_at'])?></td></tr><?php endforeach;?></tbody></table></div>
